changeSet.sql:
COMMENT ON COLUMN menu_discount_mapping.valid_from IS 'Discount validity start date and time in UTC';
COMMENT ON COLUMN menu_discount_mapping.valid_to IS 'Discount validity end date and time in UTC';
COMMENT ON COLUMN menu_discount_mapping.start_time IS 'Daily start time in UTC for discount availability';
COMMENT ON COLUMN menu_discount_mapping.end_time IS 'Daily end time in UTC for discount availability';

rollback.sql:
ALTER TABLE menu_discount_mapping
ALTER COLUMN start_time TYPE time USING start_time::time,
ALTER COLUMN end_time TYPE time USING end_time::time;

COMMENT ON COLUMN menu_discount_mapping.valid_from IS NULL;
COMMENT ON COLUMN menu_discount_mapping.valid_to IS NULL;
COMMENT ON COLUMN menu_discount_mapping.start_time IS NULL;
COMMENT ON COLUMN menu_discount_mapping.end_time IS NULL;
